export function MentionNotification({
  author = "{{author}}",
  context = "{{context}}",
  timestamp = "{{timestamp}}",
  accent = "{{accent}}",
  unread = {{unread}},
}) {
  return (
    <article role="article" style={{ display: "flex", alignItems: "flex-start", gap: 10, width: 300, boxSizing: "border-box", padding: "12px 14px", borderRadius: 10, background: unread ? "#fff" : "#FAF7F2", boxShadow: unread ? "0 2px 10px rgba(36,20,48,.08)" : "none", border: "1px solid #24143014", font: "13.5px/1.4 system-ui, sans-serif", color: "#241430" }}>
      <span aria-hidden="true" style={{ width: 28, height: 28, borderRadius: "50%", flexShrink: 0, display: "grid", placeItems: "center", background: accent, fontWeight: 700 }}>@</span>
      <div style={{ flex: 1, minWidth: 0 }}>
        <p style={{ margin: 0 }}><strong>{author}</strong> mentioned you in {context}</p>
        <time style={{ display: "block", marginTop: 4, fontSize: 11, color: "#24143080" }} dateTime={timestamp}>Today at 2:32 PM</time>
      </div>
      {unread && <span aria-label="Unread" style={{ width: 8, height: 8, borderRadius: "50%", background: "#B3261E", flexShrink: 0, marginTop: 5 }} />}
    </article>
  );
}
